//! Canonical className over actual Element attributes and owners.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><p id=target class=seed></p><div id=mount></div><form id=form class=form-class><input name=className></form><svg id=shape class=shape></svg></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://class-reflection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn element_class_name_accessor_canonical_descriptor_conversion_form_precedence_and_prototype_changes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('target'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'className'),calls=0;if(!descriptor||!descriptor.enumerable||!descriptor.configurable||descriptor.get.name!=='get className'||descriptor.set.name!=='set className'||descriptor.get.length!==0||descriptor.set.length!==1||Object.hasOwn(subject,'className'))throw 'canonical descriptor';descriptor.set.call(subject,{toString:function(){calls++;return 'A\ud800z';}});if(calls!==1||subject.className!=='A\ud800z'||descriptor.get.call(subject)!==subject.getAttribute('class')||!subject.classList.contains('A\ud800z')||subject.classList.contains('A�z'))throw 'native converted record';try{descriptor.set.call({}, {toString:function(){calls++;return 'bad';}});throw 'missing brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{descriptor.get.call(document);throw 'document brand';}catch(e){if(!(e instanceof TypeError))throw e;}try{subject.className=Symbol();throw 'symbol accepted';}catch(e){if(!(e instanceof TypeError))throw e;}if(calls!==1)throw 'brand conversion';var form=document.getElementById('form');if(form.className!==form.getElementsByTagName('input')[0]||descriptor.get.call(form)!=='form-class')throw 'form precedence';var marker={};try{subject.className={toString:function(){subject.title='effect';throw marker;}};throw 'abrupt missing';}catch(e){if(e!==marker)throw e;}if(subject.className!=='A\ud800z'||subject.title!=='effect')throw 'abrupt effects';subject.className=null;if(subject.className!=='null')throw 'null';subject.className=undefined;if(subject.className!=='undefined')throw 'undefined';Object.defineProperty(Element.prototype,'className',{get:function(){return 'author';},configurable:true});if(subject.className!=='author'||descriptor.get.call(subject)!=='undefined')throw 'override';delete Element.prototype.className;if(subject.className!==undefined||descriptor.get.call(subject)!=='undefined')throw 'delete';Object.defineProperty(Element.prototype,'className',descriptor);subject.className='restored';if(subject.className!=='restored'||subject.getAttribute('class')!=='restored')throw 'restore';
"#);}
#[test]
fn element_class_name_accessor_inert_property_uses_real_attr_observation_and_materialization(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('div');source.setAttribute('class','seed');owner.body.appendChild(source);var a=source.getAttributeNode('class'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});var calls=0;source.className={toString:function(){calls++;return 'A\ud800z';}};if(calls!==1)throw 'inert once conversion';try{source.className=Symbol();throw 'inert Symbol accepted';}catch(e){if(!(e instanceof TypeError))throw e;}if(source.className!=='A\ud800z'||source.getAttribute('class')!=='A\ud800z'||source.getAttributeNode('class')!==a||a.value!==source.className||Object.hasOwn(source,'className'))throw 'inert actual attribute';a.value='B\udfffz';if(source.className!=='B\udfffz')throw 'inert Attr read';var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='seed'||records[1].oldValue!=='A\ud800z'||records[0].target!==source)throw 'inert observation';var c=document.importNode(source,true);document.getElementById('mount').appendChild(c);if(c.className!==source.className||c===source||document.getElementsByClassName('B\udfffz')[0]!==c||c.matches('.B�z'))throw 'native import';var t=document.createElement('template');t.innerHTML='<span class=seed>held</span>';var q=t.content.firstChild,b=q.getAttributeNode('class');q.className='C\ud800z';document.getElementById('mount').appendChild(t.content);if(q.className!=='C\ud800z'||q.getAttributeNode('class')!==b||b.ownerDocument!==document||!q.classList.contains('C\ud800z'))throw 'property promotion';
"#);}
#[test]
fn element_class_name_accessor_saved_child_owner_checks_origin_before_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var subject=document.getElementById('target'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var descriptor=Object.getOwnPropertyDescriptor(frame.contentWindow.Element.prototype,'className'),calls=0;descriptor.set.call(subject,{toString:function(){calls++;return 'A\ud800z';}});if(calls!==1||descriptor.get.call(subject)!=='A\ud800z'||descriptor.get.call(frame.contentDocument.body)!=='')throw 'same-origin native class';calls=0;
"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://foreign-class-reflection.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let e=p.runtime.execute("descriptor.set.call(subject,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://class-reflection.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==0||descriptor.get.call(subject)!=='A\\ud800z')throw 'origin ordering';subject.className='fresh';if(subject.className!=='fresh')throw 'recovery';");}

#[test]
fn element_class_name_accessor_get_and_set_resource_refusal_is_atomic_with_fresh_recovery(){
 let(mut doc,mut forms,mut page)=fixture();run(&mut doc,&mut forms,&mut page,r#"var owner=document.implementation.createHTMLDocument('source'),source=owner.createElement('span');owner.body.appendChild(source);source.className='A\ud800z';var a=source.getAttributeNode('class'),watch=new MutationObserver(function(){});watch.observe(source,{attributes:true,attributeOldValue:true});var subject=document.getElementById('target');subject.className='B\udfffz';"#);page.state.rebuild(&doc).unwrap();let before=format!("{:?}",doc.nodes);let state=(page.state.retained,page.state.dom_commits,page.state.attributes.len());let limit=page.state.retained_limit;let strings=page.state.limits.host.string_bytes;
 for mode in 0..4{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,2=>page.state.retained_limit=page.state.retained,_=>page.state.limits.host.string_bytes=4};let error=page.runtime.execute(r#"source.className='long B\udfffz';"#,&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",doc.nodes),before);assert_eq!((page.state.retained,page.state.dom_commits,page.state.attributes.len()),state);page.state.retained_limit=limit;page.state.limits.host.string_bytes=strings;}
 page.begin_job();run(&mut doc,&mut forms,&mut page,r#"if(source.className!=='A\ud800z'||a.value!==source.className||watch.takeRecords().length)throw 'refusal publication';source.className='fresh C\ud800z';var records=watch.takeRecords();if(records.length!==1||records[0].oldValue!=='A\ud800z'||a.value!==source.className)throw 'fresh setter recovery';"#);
 let subject=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("target")).unwrap();let state=(page.state.retained,page.state.dom_commits);let before=format!("{:?}",doc.nodes);
 for mode in 0..3{page.begin_job();match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,_=>page.state.limits.host.string_bytes=4};let error=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.element_class_name_get(node_handle(subject)).unwrap_err();assert!(error.contains("work")||error.contains("allowance"),"{error}");assert_eq!(format!("{:?}",doc.nodes),before);assert_eq!((page.state.retained,page.state.dom_commits),state);page.state.limits.host.string_bytes=strings;}
 page.begin_job();let value=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.element_class_name_get(node_handle(subject)).unwrap();assert!(matches!(value,Value::StringUnits(u) if u==[66,0xdfff,122]));
}
#[test]
fn element_class_name_accessor_child_writes_and_svg_raw_writes_keep_existing_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'className'),shape=document.getElementById('shape'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentDocument.body,calls=0;"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 let error=p.runtime.execute("descriptor.set.call(child,{toString:function(){calls++;return 'bad';}});",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("child Element.className writes"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==0||descriptor.get.call(child)!=='')throw 'child validation before conversion';descriptor.set.call(shape,'scalar');if(descriptor.get.call(shape)!=='scalar')throw 'SVG scalar';");
 let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let error=p.runtime.execute(r#"descriptor.set.call(shape,{toString:function(){calls++;return 'A\ud800z';}});"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Unpaired attribute"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(calls!==1||descriptor.get.call(shape)!=='scalar')throw 'SVG guard';shape.className='fresh';if(shape.getAttribute('class')!=='fresh')throw 'SVG scalar recovery';");}

#[test]
fn element_class_name_accessor_no_slot_and_xml_elements_use_actual_native_attributes(){let(mut d,mut f,mut p)=fixture();let nodes=p.state.node_limit;p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','span'),xml=document.implementation.createDocument('urn:original','p:Root'),root=xml.documentElement;source.className='A\ud800z';root.className='B\udfffz';var a=source.getAttributeNode('class'),b=root.getAttributeNode('class'),descriptor=Object.getOwnPropertyDescriptor(Element.prototype,'className');if(descriptor.get.call(source)!==a.value||source.className!=='A\ud800z'||source.getAttribute('class')!==a.value||root.getAttribute('class')!=='B\udfffz'||b.value!==root.className||Object.hasOwn(source,'className')||Object.hasOwn(root,'className'))throw 'no-slot and XML actual attributes';a.value='C\udfffz';if(source.className!=='C\udfffz')throw 'live no-slot read';"#);p.state.node_limit=nodes;run(&mut d,&mut f,&mut p,"var copy=document.importNode(source,true);document.getElementById('mount').appendChild(copy);if(copy.className!=='C\\udfffz'||copy.ownerDocument!==document||source.ownerDocument!==owner||!copy.classList.contains('C\\udfffz'))throw 'no-slot materialization';");}
